                for (Page = StartPage; Page <= StopPage; Page++)
                {
                    if (OnStatus != null)
                    {
                        OnStatus(this, Rtl.Format("Printing page %d", Page), Page, TStatusType.stPrinting);
                    }
                    Rtl.Printer.Canvas.Draw(-offx, -offy, GetMetaFile(Page));
                    if (Page < StopPage)
                    {
                        Rtl.Printer.NewPage();
                    }
                }
                Rtl.Printer.EndDoc();
                if (OnStatus != null)
                {
                    OnStatus(this, "Print Job Complete", -1, TStatusType.stPrintFinished);
                }
            }
            finally
            {
                Rtl.Screen.Cursor = Rtl.crDefault;
            }
            return Result;
        }

        // Delphi: procedure TPreviewPrinter.DrawHdrFtrPage(PageNum: integer)
        public void DrawHdrFtrPage(int PageNum)
        {
            int y1 = 0;
            int y2 = 0;
            string PageStr = "";
            {
                // with TextOptions do
                y1 = UnitToY(TextOptions.HeaderMargin);
                y2 = PageHeight - UnitToY(TextOptions.FooterMargin);
                DrawAlignText(y1, TextOptions.HeaderAlign, TextOptions.Header, TextOptions.HeaderFont);
                DrawAlignText(y2, TextOptions.FooterAlign, TextOptions.Footer, TextOptions.FooterFont);
                PageStr = Rtl.Format(TextOptions.PageNumText, PageNum);
                switch (TextOptions.PrintPageNumber)
                {
                    case TPrintPageNumber.pnTop:
                        {
                            DrawAlignText(y1, TextOptions.PageNumAlign, PageStr, TextOptions.PageNumFont);
                        }
                        break;
                    case TPrintPageNumber.pnBottom:
                        {
                            DrawAlignText(y2, TextOptions.PageNumAlign, PageStr, TextOptions.PageNumFont);
                        }
                        break;
                }
            }
        }

        // Delphi: procedure TPreviewPrinter.DrawStringList(Strings: TStrings)
        public void DrawStringList(TStrings Strings)
        {
            int Line = 0;
            int Page = 0;
            int x = 0;
            int y = 0;
            int h = 0;
            tagRECT R = new tagRECT();
            bool ForceNewPage = false;
            dynamic /* TTextMetric */ tm = null;
            Rtl.Screen.Cursor = Rtl.crHourGlass;
            BeginDoc();
            {
                // with TextOptions do
                FixFont(TextOptions.BodyFont);
                FixFont(TextOptions.HeaderFont);
                FixFont(TextOptions.FooterFont);
                FixFont(TextOptions.PageNumFont);
            }
            Page = 0;
            x = UnitToX(TextOptions.MarginLeft);
            y = -2;
            {
                int __end1 = Strings.Count - 1; // Delphi evaluates the loop bound once
                for (Line = 0; Line <= __end1; Line++)
                {
                    {
                        // with TextOptions do
                        Rtl.CanvasOf(TextOptions).Font = TextOptions.BodyFont;
                        h = -1;
                        ForceNewPage = false;
                        if (OnOwnerHeight != null)
                        {
                            OnOwnerHeight(this, Line, ref h, ref ForceNewPage);
                        }
                        if (ForceNewPage)
                        {
                            y = -1;
                        }
                        if (TextOptions.DrawStyle != TDrawStyle.dsOwnerDrawVariable)
                        {
                            h = Rtl.CanvasOf(TextOptions).TextHeight("f");
                            GetTextMetrics(Rtl.CanvasOf(TextOptions).Handle, tm);
                            h = h + tm.tmInternalLeading + tm.tmExternalLeading;
                        }
                        if (h == -1)
                        {
                            new Exception("OnOwnerHeight Event returned an invalid height!");
                        }
                        if (y < 0 || y + h > UnitToY(YToUnit(PageHeight) - TextOptions.MarginBottom))
                        {
                            Page = Page + 1;
                            if (OnNewPage != null)
                            {
                                OnNewPage(this, Page);
                            }
                            if (y >= -1)
                            {
                                NewPage();
                            }
                            y = UnitToY(TextOptions.MarginTop);
                            DrawHdrFtrPage(Page);
                        }
                        R = tagRECT;
                        switch (TextOptions.DrawStyle)
                        {
                            case TDrawStyle.dsOwnerDrawFixed or TDrawStyle.dsOwnerDrawVariable:
                                {
                                    if (OnOwnerDraw != null)
                                    {
                                        OnOwnerDraw(this, Page, Line, R, Rtl.CanvasOf(TextOptions));
                                    }
                                }
                                break;
                            default:
                                {
                                    Rtl.CanvasOf(TextOptions).TextRect(R, x, y, Strings[Line]);
                                }
                                break;
                        }
                        y = y + h;
                    }
                }
            }
            EndDoc();
            Rtl.Screen.Cursor = Rtl.crDefault;
        }

        // Delphi: procedure TPreviewPrinter.DrawRichText(RE: TCustomRichEdit)
        public void DrawRichText(dynamic /* TCustomRichEdit */ RE)
        {
            int x1 = 0;
            int y1 = 0;
            int x2 = 0;
            int y2 = 0;
            tagRECT R = new tagRECT();
            int Pos = 0;
            int Page = 0;
            bool NeedWrap = false;
            TUnits OldUnits = default(TUnits);
            Rtl.Screen.Cursor = Rtl.crHourGlass;
            OldUnits = Units;
            Units = TUnits.unInches;
            try
            {
                Pos = 0;
                Page = 0;
                do
                {
                    if (Pos == 0)
                    {
                        BeginDoc();
                    }
                    else
                    {
                        NewPage();
                    }
                    Page = Page + 1;
                    DrawHdrFtrPage(Page);
                    x1 = Rtl.Round(1440.0 * TextOptions.MarginLeft);
                    y1 = Rtl.Round(1440.0 * TextOptions.MarginTop);
                    x2 = Rtl.Round(1440.0 * (XToUnit(PageWidth) - TextOptions.MarginRight));
                    y2 = Rtl.Round(1440.0 * (XToUnit(PageHeight) - TextOptions.MarginBottom));
                    R = tagRECT;
                    PrevPrinter.RE_To_Canvas(RE, Canvas, ref R, ref Pos, ref NeedWrap);
                }
                while (!!NeedWrap);
                EndDoc();
            }
            finally
            {
                Units = OldUnits;
                Rtl.Screen.Cursor = Rtl.crDefault;
            }
        }

    }

    /// <summary>
    /// Converted from Delphi class TBenMetaFileCanvas (PrevPrinter.pas).
    /// </summary>
    public class TBenMetaFileCanvas
    {
        protected internal Action<object> OldFontChanged;
        public int PPI;

        // Delphi: constructor TBenMetaFileCanvas.Create(AMetafile: TMetafile; ReferenceDevice: HDC)
        public TBenMetaFileCanvas(dynamic /* TMetafile */ AMetafile, uint ReferenceDevice)
        {
            OldFontChanged = Rtl.Font().OnChange;
            Rtl.Font().OnChange = NewFontChanged;
        }

        // Delphi: procedure TBenMetaFileCanvas.NewFontChanged(Sender: TObject)
        protected internal void NewFontChanged(object Sender)
        {
            if (OldFontChanged != null)
            {
                OldFontChanged(Sender);
            }
        }

    }

    /// <summary>
    /// Global constants, variables and routines of Delphi unit PrevPrinter.
    /// </summary>
    public static partial class PrevPrinter
    {
        public const double INCH_TO_CM = 2.54;

        // Delphi: procedure RE_To_Canvas(RE: TCustomRichEdit; Canvas: TCanvas; var R: TRect; var Pos: integer; var NeedWrap: boolean)
        internal static void RE_To_Canvas(dynamic /* TCustomRichEdit */ RE, TCanvas Canvas, ref tagRECT R, ref int Pos, ref bool NeedWrap)
        {
            dynamic /* TFormatRange */ Range = null;
            uint OutDC = (uint)0;
            int LastChar = 0;
            int MaxLen = 0;
            int LogX = 0;
            int LogY = 0;
            int OldMap = 0;
            Rtl.Assert(RE != null);
            Rtl.Assert(Rtl.IsWindow(RE.Handle));
            /* TODO: FillChar(Range, ...) */;
            LastChar = Pos;
            OutDC = Canvas.Handle;
            Range.hdc = OutDC;
            Range.hdcTarget = OutDC;
            LogX = Rtl.GetDeviceCaps(OutDC, Rtl.LOGPIXELSX);
            LogY = Rtl.GetDeviceCaps(OutDC, Rtl.LOGPIXELSY);
            if (IsRectEmpty(RE.PageRect))
            {
                Range.rc = R;
            }
            else
            {
                Range.rc.left = RE.PageRect.Left * 1440 / LogX;
                Range.rc.top = RE.PageRect.Top * 1440 / LogY;
                Range.rc.right = RE.PageRect.Right * 1440 / LogX;
                Range.rc.bottom = RE.PageRect.Bottom * 1440 / LogY;
            }
            Range.rcPage = Range.rc;
            MaxLen = RE.GetTextLen;
            Range.chrg.cpMax = -1;
            OldMap = SetMapMode(Range.hdc, MM_TEXT);
            Rtl.SendMessage(RE.Handle, EM_FORMATRANGE, 0, 0);
            Range.chrg.cpMin = LastChar;
            LastChar = Rtl.SendMessage(RE.Handle, EM_FORMATRANGE, 1, System.Convert.ToInt32(Range /* @ */));
            NeedWrap = LastChar < MaxLen && LastChar != -1;
            Rtl.SendMessage(RE.Handle, EM_FORMATRANGE, 0, 0);
            SetMapMode(OutDC, OldMap);
            Pos = LastChar;
            R = Range.rc;
        }

        /// <summary>
        /// Code from the unit&apos;s initialization section (called at application start-up).
        /// </summary>
        public static void Initialization()
        {
        }
    }
